@sealed
class AppNodeImpl extends RustOpaque implements AppNode {
  // Not to be used by end users
  AppNodeImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  AppNodeImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_AppNode,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_AppNode,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_AppNodePtr,
  );

  /// Add a map pin to a group and optionally publish via gossip.
  Future<void> addPin({
    required String groupId,
    required String label,
    required String location,
  }) => RustLib.instance.api.crateApiAppNodeAddPin(
    that: this,
    groupId: groupId,
    label: label,
    location: location,
  );

  /// Record the current location and optionally publish via gossip.
  Future<void> checkIn({
    required String groupId,
    String? stageId,
    String? customLocation,
  }) => RustLib.instance.api.crateApiAppNodeCheckIn(
    that: this,
    groupId: groupId,
    stageId: stageId,
    customLocation: customLocation,
  );

  /// Connect this node to the Festival Durable Object relay at `url`.
  ///
  /// `festival_id` is used to look up the cached Ed25519 public key for
  /// verifying signed updates. Call `set_festival_public_key` first.
  Future<void> connectRelay({
    required String url,
    required String festivalId,
  }) => RustLib.instance.api.crateApiAppNodeConnectRelay(
    that: this,
    url: url,
    festivalId: festivalId,
  );

  /// Create a new group and return its ID + shareable invite payload.
  Future<GroupCreateResultDto> createGroup({
    required String festivalId,
    required String name,
    required String displayName,
  }) => RustLib.instance.api.crateApiAppNodeCreateGroup(
    that: this,
    festivalId: festivalId,
    name: name,
    displayName: displayName,
  );

  /// Delete a group by ID.
  Future<void> deleteGroup({required String id}) =>
      RustLib.instance.api.crateApiAppNodeDeleteGroup(that: this, id: id);

  /// Derive the Ed25519 identity from a WebAuthn PRF output (32 bytes).
  Future<String> deriveIdentityFromPrf({required List<int> prfOutput}) =>
      RustLib.instance.api.crateApiAppNodeDeriveIdentityFromPrf(
        that: this,
        prfOutput: prfOutput,
      );

  /// Load the stored attestation, if any.
  Future<AttestationDto?> getAttestation() =>
      RustLib.instance.api.crateApiAppNodeGetAttestation(that: this);

  /// Get the current authentication state.
  Future<AuthStateDto> getAuthState() =>
      RustLib.instance.api.crateApiAppNodeGetAuthState(that: this);

  /// Return paginated chat history for a topic string.
  Future<List<ChatMessageDto>> getChatHistory({
    required String topic,
    required int limit,
    required int offset,
  }) => RustLib.instance.api.crateApiAppNodeGetChatHistory(
    that: this,
    topic: topic,
    limit: limit,
    offset: offset,
  );

  /// Fetch chat messages for a topic with pagination.
  Future<List<ChatMessageDto>> getChatMessages({
    required String topic,
    required int limit,
    required int offset,
  }) => RustLib.instance.api.crateApiAppNodeGetChatMessages(
    that: this,
    topic: topic,
    limit: limit,
    offset: offset,
  );

  /// Read the current state of a group from the local Yrs doc.
  Future<GroupStateDto> getGroupState({required String groupId}) => RustLib
      .instance
      .api
      .crateApiAppNodeGetGroupState(that: this, groupId: groupId);

  /// Return all groups for the given festival.
  Future<List<GroupInfo>> getGroups({required String festivalId}) => RustLib
      .instance
      .api
      .crateApiAppNodeGetGroups(that: this, festivalId: festivalId);

  /// Return the local identity (user_id + optional display_name).
  Future<IdentityDto> getIdentity() =>
      RustLib.instance.api.crateApiAppNodeGetIdentity(that: this);

  /// Read the lineup from the local Yrs doc for a festival.
  ///
  /// The Yrs doc at `festival/{id}/state` has separate root-map keys:
  /// `"stages"`, `"days"`, `"sets"` — each a JSON array string that
  /// arrives via signed gossip updates and merges independently.
  ///
  /// Returns `None` if no lineup data has synced yet.
  Future<LineupDto?> getLineup({required String festivalId}) => RustLib
      .instance
      .api
      .crateApiAppNodeGetLineup(that: this, festivalId: festivalId);

  /// Get the hex-encoded Ed25519 public key of the local identity.
  Future<String> getPublicKeyHex() =>
      RustLib.instance.api.crateApiAppNodeGetPublicKeyHex(that: this);

  /// Return the set IDs that are starred for the given festival.
  Future<List<String>> getStars({required String festivalId}) => RustLib
      .instance
      .api
      .crateApiAppNodeGetStars(that: this, festivalId: festivalId);

  /// Get a snapshot of transport status (no rate computation).
  Future<TransportStatusDto> getTransportStatus() =>
      RustLib.instance.api.crateApiAppNodeGetTransportStatus(that: this);

  /// Read the weather forecast from the local Yrs doc for a festival.
  ///
  /// Returns `None` if no weather data has synced yet.
  Future<WeatherForecastDto?> getWeather({required String festivalId}) =>
      RustLib.instance.api.crateApiAppNodeGetWeather(
        that: this,
        festivalId: festivalId,
      );

  /// Join an existing group from an invite payload.
  Future<GroupJoinResultDto> joinGroup({
    required String invitePayload,
    required String displayName,
  }) => RustLib.instance.api.crateApiAppNodeJoinGroup(
    that: this,
    invitePayload: invitePayload,
    displayName: displayName,
  );

  /// Leave a group.
  Future<void> leaveGroup({required String groupId}) => RustLib.instance.api
      .crateApiAppNodeLeaveGroup(that: this, groupId: groupId);

  /// Broadcast a chat message on the given gossip topic.
  Future<void> publishChat({
    required String topic,
    required ChatMessageDto message,
  }) => RustLib.instance.api.crateApiAppNodePublishChat(
    that: this,
    topic: topic,
    message: message,
  );

  /// Persist a group record for a festival.
  Future<void> saveGroup({
    required String id,
    required String festivalId,
    required String name,
    required List<int> key,
  }) => RustLib.instance.api.crateApiAppNodeSaveGroup(
    that: this,
    id: id,
    festivalId: festivalId,
    name: name,
    key: key,
  );

  /// Send a festival chat message (plaintext) and broadcast it via gossip if
  /// networking is active. Returns the persisted message.
  Future<ChatMessageDto> sendFestivalChat({
    required String festivalId,
    String? stageId,
    required String text,
  }) => RustLib.instance.api.crateApiAppNodeSendFestivalChat(
    that: this,
    festivalId: festivalId,
    stageId: stageId,
    text: text,
  );

  /// Send an encrypted group chat message and broadcast it via gossip if
  /// networking is active. Returns the persisted message.
  Future<ChatMessageDto> sendGroupChat({
    required String groupId,
    required String text,
  }) => RustLib.instance.api.crateApiAppNodeSendGroupChat(
    that: this,
    groupId: groupId,
    text: text,
  );

  /// Persist a display name for the local user.
  Future<void> setDisplayName({required String name}) => RustLib.instance.api
      .crateApiAppNodeSetDisplayName(that: this, name: name);

  /// Cache a festival's Ed25519 public key (hex-encoded, 64 chars).
  Future<void> setFestivalPublicKey({
    required String festivalId,
    required String hexKey,
  }) => RustLib.instance.api.crateApiAppNodeSetFestivalPublicKey(
    that: this,
    festivalId: festivalId,
    hexKey: hexKey,
  );

  /// Sign an arbitrary message with the local Ed25519 identity key.
  Future<String> signMessage({required String message}) => RustLib.instance.api
      .crateApiAppNodeSignMessage(that: this, message: message);

  /// Store an attestation received from the MainDO.
  Future<void> storeAttestation({
    required String message,
    required String signature,
    required String issuer,
  }) => RustLib.instance.api.crateApiAppNodeStoreAttestation(
    that: this,
    message: message,
    signature: signature,
    issuer: issuer,
  );

  /// Subscribe to all chat topics for a festival (general + campsite + per-stage).
  Future<void> subscribeChatTopics({
    required String festivalId,
    required List<String> stageIds,
  }) => RustLib.instance.api.crateApiAppNodeSubscribeChatTopics(
    that: this,
    festivalId: festivalId,
    stageIds: stageIds,
  );

  /// Subscribe to the gossip topic for a festival and perform a state vector
  /// exchange with the DO so we only receive updates we don't already have.
  ///
  /// Registers the festival as a resource in the registry, then delegates
  /// subscribe + catch-up to the SyncOrchestrator.
  Future<void> subscribeFestival({required String festivalId}) => RustLib
      .instance
      .api
      .crateApiAppNodeSubscribeFestival(that: this, festivalId: festivalId);

  /// Toggle a star on a set. Returns the new starred state (`true` = now starred).
  Future<bool> toggleStar({
    required String festivalId,
    required String setId,
  }) => RustLib.instance.api.crateApiAppNodeToggleStar(
    that: this,
    festivalId: festivalId,
    setId: setId,
  );

  /// Update the shared stars for the current user in a group.
  Future<void> updateSharedStars({
    required String groupId,
    required List<String> setIds,
  }) => RustLib.instance.api.crateApiAppNodeUpdateSharedStars(
    that: this,
    groupId: groupId,
    setIds: setIds,
  );

  /// Watch chat messages for a topic — emits current messages, then updates.
  Future<Stream<List<ChatMessageDto>>> watchChat({
    required String topic,
    required int lastN,
  }) => RustLib.instance.api.crateApiAppNodeWatchChat(
    that: this,
    topic: topic,
    lastN: lastN,
  );

  /// Watch group state — emits current state, then updates on changes.
  Future<Stream<GroupStateDto>> watchGroupState({required String groupId}) =>
      RustLib.instance.api.crateApiAppNodeWatchGroupState(
        that: this,
        groupId: groupId,
      );

  /// Watch festival lineup — emits current state, then updates on changes.
  ///
  /// The stream emits the current lineup immediately, then re-emits whenever
  /// the lineup document is updated (via sync or local changes).
  Future<Stream<LineupDto?>> watchLineup({required String festivalId}) =>
      RustLib.instance.api.crateApiAppNodeWatchLineup(
        that: this,
        festivalId: festivalId,
      );

  /// Watch sync status — emits current status, then updates on changes.
  Future<Stream<SyncStatusDto>> watchSyncStatus() =>
      RustLib.instance.api.crateApiAppNodeWatchSyncStatus(that: this);

  /// Watch transport status — emits relay + BLE state with bandwidth
  /// rates computed by diffing cumulative counters every second.
  Future<Stream<TransportStatusDto>> watchTransportStatus() =>
      RustLib.instance.api.crateApiAppNodeWatchTransportStatus(that: this);

  /// Watch weather forecast — emits current forecast, then updates on changes.
  Future<Stream<WeatherForecastDto?>> watchWeather({
    required String festivalId,
  }) => RustLib.instance.api.crateApiAppNodeWatchWeather(
    that: this,
    festivalId: festivalId,
  );
}
